SELECT MIN(L.ID) ID, MIN(L.TITULO) NOME, MAX(NULLIF(L.AUTOR, '')) AUTOR, COUNT(DISTINCT L.VIDEO_ID) VIDEOS, MAX(N.ID) NID, MAX(N.SUGESTAO_TITULO) SUG_TITULO, MAX(N.SUGESTAO_AUTOR) SUG_AUTOR, MAX(N.MOTIVO) MOTIVO, MAX(N.CERTEZA) CERTEZA, MAX(N.TIPO_SUG) TIPO FROM LIVROS_INDICADOS L LEFT JOIN LIVROS_NOMES N ON N.NOME = L.TITULO COLLATE utf8mb4_0900_ai_ci WHERE (N.ID IS NULL OR N.ESTADO = 'PENDENTE') AND ('{{busca}}' = '' OR L.TITULO COLLATE utf8mb4_0900_ai_ci LIKE CONCAT('%', '{{busca}}', '%')) AND ('{{tipo}}' = '' OR ('{{tipo}}' = 'semtipo' AND N.TIPO_SUG IS NULL) OR N.TIPO_SUG = '{{tipo}}') AND ('{{origem}}' = '' OR ('{{origem}}' = 'claude' AND N.CONFERIDO = 'IMPORTADO') OR ('{{origem}}' = 'app' AND N.ID IS NOT NULL AND COALESCE(N.CONFERIDO, '') <> 'IMPORTADO')) AND ('{{faixa}}' = '' OR ('{{faixa}}' = 'alta' AND N.CERTEZA >= 90) OR ('{{faixa}}' = 'baixa' AND N.ID IS NOT NULL AND COALESCE(N.CERTEZA, 0) < 90)) AND ('{{grupo}}' <> '1' OR N.SUGESTAO_TITULO IN (SELECT G.T FROM (SELECT SUGESTAO_TITULO T FROM LIVROS_NOMES WHERE ESTADO = 'PENDENTE' AND SUGESTAO_TITULO IS NOT NULL GROUP BY SUGESTAO_TITULO HAVING COUNT(*) >= 2) G)) AND ('{{filtro}}' = '' OR ('{{filtro}}' = 'sug' AND N.ID IS NOT NULL) OR ('{{filtro}}' = 'novo' AND N.ID IS NULL) OR ('{{filtro}}' = 'alta' AND N.CERTEZA >= 90) OR ('{{filtro}}' = 'baixa' AND N.ID IS NOT NULL AND COALESCE(N.CERTEZA, 0) < 90) OR ('{{filtro}}' IN ('novoautor', 'novosolo') AND N.ID IS NULL) OR '{{filtro}}' = 'semautor' OR ('{{filtro}}' = 'grupo' AND N.SUGESTAO_TITULO IN (SELECT G.T FROM (SELECT SUGESTAO_TITULO T FROM LIVROS_NOMES WHERE ESTADO = 'PENDENTE' AND SUGESTAO_TITULO IS NOT NULL GROUP BY SUGESTAO_TITULO HAVING COUNT(*) >= 2) G))) GROUP BY L.TITULO COLLATE utf8mb4_0900_ai_ci HAVING ('{{campos}}' = '' OR ('{{campos}}' = 'ambos' AND MAX(NULLIF(N.SUGESTAO_TITULO, '')) IS NOT NULL AND COALESCE(MAX(NULLIF(N.SUGESTAO_AUTOR, '')), MAX(NULLIF(L.AUTOR, ''))) IS NOT NULL) OR ('{{campos}}' = 'titulo' AND MAX(NULLIF(N.SUGESTAO_TITULO, '')) IS NOT NULL AND NOT (COALESCE(MAX(NULLIF(N.SUGESTAO_AUTOR, '')), MAX(NULLIF(L.AUTOR, ''))) IS NOT NULL)) OR ('{{campos}}' = 'autor' AND NOT (MAX(NULLIF(N.SUGESTAO_TITULO, '')) IS NOT NULL) AND COALESCE(MAX(NULLIF(N.SUGESTAO_AUTOR, '')), MAX(NULLIF(L.AUTOR, ''))) IS NOT NULL) OR ('{{campos}}' = 'nenhum' AND NOT (MAX(NULLIF(N.SUGESTAO_TITULO, '')) IS NOT NULL) AND NOT (COALESCE(MAX(NULLIF(N.SUGESTAO_AUTOR, '')), MAX(NULLIF(L.AUTOR, ''))) IS NOT NULL))) AND ('{{filtro}}' <> 'novoautor' OR MAX(NULLIF(L.AUTOR, '')) IS NOT NULL) AND ('{{filtro}}' <> 'semautor' OR (MAX(NULLIF(L.AUTOR, '')) IS NULL AND MAX(NULLIF(N.SUGESTAO_AUTOR, '')) IS NULL)) AND ('{{filtro}}' <> 'novosolo' OR MAX(NULLIF(L.AUTOR, '')) IS NULL) ORDER BY IF('{{grupo}}' = '1', MAX(N.SUGESTAO_TITULO), '') ASC, (MAX(N.ID) IS NOT NULL) DESC, MAX(N.CERTEZA) DESC, VIDEOS DESC, NOME LIMIT {{limit}} OFFSET {{offset}}